    for attempt in range(max_attempts):
        if self.is_sm_service_up():
            if self.is_vim_api_ready():
                return True
        time.sleep(1)
    return False

def is_sm_service_up(self):
    # Check if the SM service is up by querying its PID
    pid = self.get_sm_service_pid()
    return pid is not None

def is_vim_api_ready(self):
    # Check if the VIM API is ready by querying its capability
    response = self.call_application('vim-api', 'check_capability')
    return response.get('is_ready', False)
